<template>
<section class="canonical-desk ledger-page portfolio-page">
<h1>資金與績效</h1><p>記錄實際現金流、股息、費稅、拆併股與換匯，對照含現金的整體資產。價格與匯率由你提供日期與數值。</p>
<PrivateStateStatus :loading="loading" :loaded="loaded" :error="error" :message="message" :storage="storage" :auth-required="authRequired" reload-label="載入最新後重新核對" @reload="recheckDraft"/>
<template v-if="loaded">
<details open><summary>計算設定</summary><form @focusin="beginEdit" @input="beginEdit();settingsEditing=true" @submit.prevent="saveSettings"><div class="form-grid"><label>總資產計算幣別<input v-model="settings.base_currency" required maxlength="3" /></label><label>比較基準名稱<input v-model="settings.benchmark_name" maxlength="200" placeholder="自行提供的總報酬指數" /></label><label>基準口徑<select v-model="settings.benchmark_kind"><option value="total_return">總報酬（含股息）</option><option value="price">僅價格（未含股息）</option></select></label></div><label class="check-label"><input type="checkbox" v-model="settings.history_complete"/>我已核對本組合交易、期初資金、全部入出金、股息、費稅與拆併股記錄完整</label><button :disabled="busy">儲存計算設定</button></form></details>
<h2>資產對帳</h2><label>資產估值日期<input type="date" v-model="asOf" /></label><p v-if="!state.records.length&&!finance.events.length" class="empty-state">尚無交易與資金記錄。請先記錄期初資金及實際成交。</p>
<template v-else><p class="portfolio-total">{{ snapshot.total_value===null?'尚缺完整估值':number(snapshot.total_value)+' '+snapshot.base_currency }} · {{ asOf }}</p><ul v-if="snapshot.gaps?.length" class="canonical-alert"><li v-for="gap in snapshot.gaps" :key="gap">{{ gap }}</li></ul><div class="table-scroll"><table class="ledger-table"><caption>各幣別現金餘額</caption><thead><tr><th>幣別</th><th>現金</th></tr></thead><tbody><tr v-for="(amount,currency) in snapshot.cash" :key="currency"><th>{{ currency }}</th><td>{{ number(amount) }}</td></tr></tbody></table></div><div class="table-scroll"><table class="ledger-table"><caption>股數與剩餘成本（已含拆併股）</caption><thead><tr><th>標的／幣別</th><th>股數</th><th>剩餘成本</th><th>已實現</th><th>當日市值</th><th>當日換算值</th></tr></thead><tbody><tr v-for="p in snapshot.positions" :key="p.ticker+p.currency"><th>{{ p.ticker }} / {{ p.currency }}</th><td>{{ number(p.quantity) }}</td><td>{{ number(p.cost_basis) }}</td><td>{{ number(p.realized) }}</td><td>{{ p.market_value===null?'缺當日價格':number(p.market_value) }}</td><td>{{ p.base_value===null?'缺換算資料':number(p.base_value) }}</td></tr></tbody></table></div></template>
<details><summary>記錄入出金、股息與公司行動</summary><form @focusin="beginEdit" @input="beginEdit" class="form-panel" @submit.prevent="saveEvent"><h3>{{ eventForm.id?'修改資金事件':'新增資金事件' }}</h3><div class="form-grid"><label>事件日期<input type="date" v-model="eventForm.date" required /></label><label>資金事件類型<select v-model="eventForm.type" @change="resetEventType"><option v-for="(label,type) in types" :key="type" :value="type">{{ label }}</option></select></label><label>事件幣別<input v-model="eventForm.currency" maxlength="3" required /></label><label v-if="eventForm.type!=='SPLIT'">實際金額（填正數）<input type="number" v-model="eventForm.amount" min="0.00000001" step="any" required /></label><label v-if="['DIVIDEND','SPLIT'].includes(eventForm.type)">標的<input v-model="eventForm.ticker" maxlength="32" required /></label><label v-if="eventForm.type==='SPLIT'">每一舊股換成幾新股<input type="number" v-model="eventForm.ratio" min="0.00000001" step="any" required /></label><template v-if="eventForm.type==='FX'"><label>取得幣別<input v-model="eventForm.to_currency" maxlength="3" required /></label><label>實際取得金額<input type="number" v-model="eventForm.to_amount" min="0.00000001" step="any" required /></label></template><label v-if="['DEPOSIT','WITHDRAWAL'].includes(eventForm.type)">同日外部入出金順序（0 起，不能重複）<input type="number" v-model="eventForm.order" min="0" max="1000000" step="1" required /></label></div><label>記錄說明<textarea v-model="eventForm.note" maxlength="5000" rows="2" /></label><p class="muted">買卖費用已在成交扣除，這裡只記其他實際費稅。股息填入帳金額；若填稅前金額，另記實際稅款。拆併股先於同日成交；比例 2 代表一股拆成兩股，0.1 代表十股併一股。</p><div class="button-row"><button :disabled="busy">儲存資金事件</button><button type="button" @click="eventForm=newEvent();resetBase()">取消事件編輯</button></div></form>
<p v-if="!finance.events.length" class="empty-state">尚無資金事件。</p><article v-for="e in sortedEvents" :key="e.id" class="decision-card"><h3>{{ e.date }} · {{ types[e.type] }}</h3><p>{{ e.ticker }} {{ e.type==='SPLIT'?'每舊股換 '+e.ratio+' 新股':number(e.amount)+' '+e.currency }} {{ e.type==='FX'?'→ '+number(e.to_amount)+' '+e.to_currency:'' }}</p><p>{{ e.note || '未記錄說明' }}</p><p v-if="['DEPOSIT','WITHDRAWAL'].includes(e.type)" class="muted">同日順序 {{ e.order }} · 事件 ID {{ e.id }}</p><div class="button-row"><button :disabled="busy" @click="eventForm={...e}">修改事件</button><button :disabled="busy" @click="removeEvent(e)">移除事件</button></div></article></details>
<details><summary>記錄帶日期的價格與匯率</summary><form @focusin="beginEdit" @input="beginEdit" class="form-panel" @submit.prevent="savePrice"><h3>當日股價</h3><div class="form-grid"><label>價格標的<input v-model="price.ticker" required maxlength="32" /></label><label>價格幣別<input v-model="price.currency" required maxlength="3" /></label><label>價格日期<input type="date" v-model="price.date" required /></label><label>當日價格<input type="number" step="any" min="0.00000001" v-model="price.price" required /></label></div><button :disabled="busy">儲存當日價格</button></form><div v-for="p in finance.prices" :key="p.date+p.ticker+p.currency" class="quote-row">{{ p.date }} {{ p.ticker }} {{ p.currency }} {{ number(p.price) }} <button :disabled="busy" @click="removeRow('prices',p)">移除當日價格</button></div>
<form @focusin="beginEdit" @input="beginEdit" class="form-panel" @submit.prevent="saveFx"><h3>當日換算匯率</h3><p>1 單位來源幣別＝多少 {{ finance.settings.base_currency }}。換匯成交仍用前面的實際付出／取得金額。</p><div class="form-grid"><label>匯率日期<input type="date" v-model="fx.date" required /></label><label>來源幣別<input v-model="fx.currency" required maxlength="3" /></label><label>每來源幣別可換多少計算幣別<input type="number" step="any" min="0.00000001" v-model="fx.rate" required /></label></div><button :disabled="busy">儲存當日匯率</button></form><div v-for="r in finance.fx" :key="r.date+r.currency+r.base_currency" class="quote-row">{{ r.date }} · 1 {{ r.currency }} = {{ number(r.rate) }} {{ r.base_currency }} <button :disabled="busy" @click="removeRow('fx',r)">移除當日匯率</button></div></details>
<h2>整體報酬</h2><div class="form-grid"><label>報酬起日<input type="date" v-model="start" /></label><label>報酬迄日<input type="date" v-model="end" /></label></div><div class="table-scroll"><table class="ledger-table"><thead><tr><th>指標</th><th>結果</th><th>代表什麼</th></tr></thead><tbody><tr><th>TWR · 期間時間加權報酬</th><td>{{ percent(returns.twr) }}</td><td>把各次外部入出金影響拆開，看這段期間組合的表現。</td></tr><tr><th>MWR · 年化金額加權報酬</th><td>{{ percent(returns.mwr) }}</td><td>把你何時投入多少錢一併考慮；以實際天數／365 年化。</td></tr><tr><th>{{ finance.settings.benchmark_name||'基準' }} · 期間報酬</th><td>{{ percent(returns.benchmark_return) }}</td><td>{{ finance.settings.benchmark_kind==='total_return'?'含股息總報酬':'僅價格，未含股息' }}</td></tr><tr><th>TWR 與同口徑基準差</th><td>{{ returns.excess_return===null?'資料不足／口徑不同':number(returns.excess_return*100)+' 個百分點' }}</td><td>同幣別、同起訖日且含股息，才比較差距。</td></tr></tbody></table></div><ul v-if="returns.gaps.length" class="canonical-alert"><li v-for="gap in returns.gaps" :key="gap">{{ gap }}</li></ul>
<details><summary>記錄總資產估值與基準值</summary><form @focusin="beginEdit" @input="beginEdit" class="form-panel" @submit.prevent="saveValue"><h3>總資產估值（含現金）</h3><div class="form-grid"><label>估值日期<input v-model="valuation.date" type="date" required /></label><label>總資產估值金額（{{ finance.settings.base_currency }}）<input v-model="valuation.value" type="number" min="0" step="any" required /></label><label>估值時間點<select v-model="valuation.phase"><option value="close">當日結束／期間起訖</option><option value="before_flow">外部入出金前</option><option value="after_flow">外部入出金後</option></select></label><label v-if="valuation.phase!=='close'">對應外部入出金<select v-model="valuation.flow_id" required><option value="">請選擇</option><option v-for="e in externalFlows.filter(e=>e.date===valuation.date)" :key="e.id" :value="e.id">{{ types[e.type] }} {{ e.amount }} {{ e.currency }} · 順序 {{ e.order }} · {{ e.id }}</option></select></label></div><p>每次入出金前後估值差，須等於當次入出金換算金額。含持股、現金與全部已記錄費稅；不要只填股票市值。</p><button :disabled="busy">儲存總資產估值</button></form><div v-for="v in finance.valuations" :key="v.id" class="quote-row">{{ v.date }} · {{ phases[v.phase] }} {{ number(v.value) }} {{ v.currency }} <span>{{ v.flow_id }}</span><button :disabled="busy" @click="removeRow('valuations',v)">移除總資產估值</button></div>
<form @focusin="beginEdit" @input="beginEdit" class="form-panel" @submit.prevent="saveBenchmark"><h3>基準指數值</h3><div class="form-grid"><label>基準日期<input v-model="benchmark.date" type="date" required /></label><label>基準值（{{ finance.settings.base_currency }}口徑）<input v-model="benchmark.value" type="number" min="0.00000001" step="any" required /></label></div><button :disabled="busy">儲存基準值</button></form><div v-for="b in finance.benchmark" :key="b.date+b.currency" class="quote-row">{{ b.date }} {{ b.currency }} {{ number(b.value) }} <button :disabled="busy" @click="removeRow('benchmark',b)">移除基準值</button></div></details>
<details><summary>計算方式與需要的資料</summary><p>這是一組手動合併帳本，使用平均成本與成交日現金。各日收盤現金不足會列出缺口；尚未支援融資或交割延遲。匯率与股價只採指定日，不沿用舊日數值。拆併股改股數、保留成本；配股、分拆公司、併購或實物轉入請先另行對帳。</p><p>TWR＝各段（入出金前資產 ÷ 上次入出金後資產）乘積，再乘期末／最後段起點，最後減 1。缺任何邊界估值即留空。MWR 求解期初投入、各筆外部入出金與期末價值的 XIRR；有多次現金流符號變化或無穩定解則留空。買賣和股息留在帳內，屬內部流動。</p><p><a href="https://help.portfolio-performance.info/en/concepts/performance/time-weighted/" target="_blank" rel="noopener noreferrer">時間加權報酬方法</a> · <a href="https://help.portfolio-performance.info/en/concepts/performance/money-weighted/" target="_blank" rel="noopener noreferrer">金額加權報酬方法</a> · <a href="?workspace=ledger">完整 JSON 備份與歷史</a></p></details>
</template></section>
</template>
<script setup>
import {computed,ref,watch,onMounted,onUnmounted} from 'vue';
import PrivateStateStatus from './PrivateStateStatus.vue';import {usePrivateState} from './private-state.js';import {emptyFinance,replayPortfolio,portfolioReturns} from './portfolio-core.mjs';
const {state,loaded,loading,busy,error,message,storage,authRequired,scope,load,save,beginEdit,resetBase,recheckDraft,context}=usePrivateState();
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const types={DEPOSIT:'外部入金',WITHDRAWAL:'外部出金',DIVIDEND:'實收股息',INTEREST:'實收利息',FEE:'其他實付費用',TAX:'實付稅款',SPLIT:'拆併股',FX:'實際換匯'},phases={close:'當日結束',before_flow:'入出金前',after_flow:'入出金後'};
const finance=computed(()=>state.value.finance||emptyFinance()),settings=ref({...emptyFinance().settings});
const newEvent=()=>({id:'',date:today(),type:'DEPOSIT',currency:'USD',amount:'',ticker:'',ratio:1,to_currency:'',to_amount:0,note:'',order:0,created_at:''});
const eventForm=ref(newEvent()),price=ref({date:today(),ticker:'',currency:'USD',price:''}),fx=ref({date:today(),currency:'',rate:''}),valuation=ref({date:today(),value:'',phase:'close',flow_id:''}),benchmark=ref({date:today(),value:''});
const asOf=ref(today()),start=ref(''),end=ref(today());
const snapshot=computed(()=>replayPortfolio(state.value.records,finance.value,asOf.value)),returns=computed(()=>portfolioReturns(finance.value,start.value,end.value));
const sortedEvents=computed(()=>[...finance.value.events].sort((a,b)=>b.date.localeCompare(a.date)||a.order-b.order)),externalFlows=computed(()=>finance.value.events.filter(e=>['DEPOSIT','WITHDRAWAL'].includes(e.type)));
const number=x=>Number(x).toLocaleString('zh-TW',{maximumFractionDigits:6}),percent=x=>x===null?'資料不足':number(x*100)+'%';
const settingsEditing=ref(false);
watch(()=>finance.value.settings,s=>{if(!settingsEditing.value)settings.value={...s}},{immediate:true});
watch(scope,(c,p)=>{if(p&&c!==p){settingsEditing.value=false;settings.value={...emptyFinance().settings};eventForm.value=newEvent();price.value={date:today(),ticker:'',currency:'USD',price:''};fx.value={date:today(),currency:'',rate:''};valuation.value={date:today(),value:'',phase:'close',flow_id:''};benchmark.value={date:today(),value:''};}});
const persist=(f,msg)=>save({...state.value,finance:f},msg);
async function saveSettings(){if(await persist({...finance.value,settings:{...settings.value,base_currency:settings.value.base_currency.trim().toUpperCase()}},'計算設定已儲存。'))settingsEditing.value=false;}
function resetEventType(){eventForm.value.amount=eventForm.value.type==='SPLIT'?0:'';eventForm.value.ticker='';eventForm.value.ratio=1;eventForm.value.to_currency='';eventForm.value.to_amount=0;}
async function saveEvent(){const f=eventForm.value,e={...f,id:f.id||crypto.randomUUID(),currency:f.currency.trim().toUpperCase(),ticker:f.ticker.trim().toUpperCase(),amount:Number(f.amount),ratio:Number(f.ratio),to_currency:f.to_currency.trim().toUpperCase(),to_amount:Number(f.to_amount),order:Number(f.order),created_at:f.created_at||new Date().toISOString()};if(await persist({...finance.value,events:[...finance.value.events.filter(x=>x.id!==e.id),e]},'資金事件已儲存，原資料留於历史。'))eventForm.value=newEvent();}
async function removeEvent(e){if(finance.value.valuations.some(v=>v.flow_id===e.id)){error.value='此入出金已有前後估值，請先核對並移除對應估值。';return;}await persist({...finance.value,events:finance.value.events.filter(x=>x.id!==e.id)},'資金事件已移除，原版本可回查。');}
async function savePrice(){const p={...price.value,ticker:price.value.ticker.trim().toUpperCase(),currency:price.value.currency.trim().toUpperCase(),price:Number(price.value.price)};if(await persist({...finance.value,prices:[...finance.value.prices.filter(x=>!(x.ticker===p.ticker&&x.currency===p.currency&&x.date===p.date)),p]},'當日價格已儲存。'))price.value.price='';}
async function saveFx(){const r={date:fx.value.date,currency:fx.value.currency.trim().toUpperCase(),base_currency:finance.value.settings.base_currency,rate:Number(fx.value.rate)};if(await persist({...finance.value,fx:[...finance.value.fx.filter(x=>!(x.date===r.date&&x.currency===r.currency&&x.base_currency===r.base_currency)),r]},'當日匯率已儲存。'))fx.value.rate='';}
async function saveValue(){const v={...valuation.value,id:crypto.randomUUID(),currency:finance.value.settings.base_currency,value:Number(valuation.value.value),flow_id:valuation.value.phase==='close'?'':valuation.value.flow_id};await persist({...finance.value,valuations:[...finance.value.valuations.filter(x=>!(x.date===v.date&&x.currency===v.currency&&x.phase===v.phase&&x.flow_id===v.flow_id)),v]},'總資產估值已儲存。');}
async function saveBenchmark(){const b={...benchmark.value,currency:finance.value.settings.base_currency,value:Number(benchmark.value.value)};await persist({...finance.value,benchmark:[...finance.value.benchmark.filter(x=>!(x.date===b.date&&x.currency===b.currency)),b]},'基準值已儲存。');}
async function removeRow(key,row){await persist({...finance.value,[key]:finance.value[key].filter(x=>JSON.stringify(x)!==JSON.stringify(row))},'記錄已移除，原版本可回查。');}
function readUrl(){const p=new URLSearchParams(location.search);asOf.value=p.get('assetDate')||today();start.value=p.get('returnStart')||'';end.value=p.get('returnEnd')||today();}
watch([asOf,start,end],()=>{const p=new URLSearchParams({workspace:'portfolio',assetDate:asOf.value,returnStart:start.value,returnEnd:end.value});history.replaceState(history.state,'','?'+p);});
readUrl();onMounted(()=>window.addEventListener('popstate',readUrl));onUnmounted(()=>window.removeEventListener('popstate',readUrl));
</script>
